class Tree:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None
def insert(t, k):
    if t is None:
        return Tree(k)
    if k < t.key:
        t.left = insert(t.left, k)
    else:
        t.right = insert(t.right, k)
    return t
def inorder(t, out):
    if t:
        inorder(t.left, out)
        out.append(t.key)
        inorder(t.right, out)
    return out
