import heapq
graph = {"a": [("b", 4), ("c", 1)], "b": [("d", 1)], "c": [("b", 2), ("d", 5)], "d": []}
dist = {"a": 0}
pq = [(0, "a")]
while pq:
    d, node = heapq.heappop(pq)
    if d > dist.get(node, 10 ** 9):
        continue
    for nxt, w in graph[node]:
        nd = d + w
        if nd < dist.get(nxt, 10 ** 9):
            dist[nxt] = nd
            heapq.heappush(pq, (nd, nxt))
print(sorted(dist.items()))

